 c=d.contact[k]; n1=m.geom(c.geom1).name;n2=m.geom(c.geom2).name
 if ('robot0' in n1+' '+n2 or 'gripper0' in n1+' '+n2) and 'sink_left_group' in n1+' '+n2:
